Run these tests with the previously defined `peak_demand` function. The oracle counts bookings directly at each integer slot, independently of event ordering.

```python
import unittest


def slot_oracle(bookings):
    covered = [
        sum(start <= slot < end for _, start, end in bookings)
        for slot in range(
            min((start for _, start, _ in bookings), default=0),
            max((end for _, _, end in bookings), default=0),
        )
    ]
    return max(covered, default=0)


class PeakDemandTests(unittest.TestCase):
    def test_valid_intervals(self):
        cases = [
            ([], 0),
            ([('A', 1, 4), ('B', 4, 7)], 1),
            ([('A', 1, 5), ('B', 2, 4), ('C', 3, 6)], 3),
            ([('D', 5, 5)], 0),
            ([('A', 1, 4), ('B', 4, 7), ('C', 2, 5),
              ('D', 5, 5), ('E', 6, 8)], 2),
        ]
        for bookings, expected in cases:
            with self.subTest(bookings=bookings):
                self.assertEqual(slot_oracle(bookings), expected)
                self.assertEqual(peak_demand(bookings), expected)

    def test_invalid_intervals(self):
        with self.assertRaises(ValueError):
            peak_demand([('A', 4, 3)])
        with self.assertRaises(TypeError):
            peak_demand([('A', 1, 2.5)])


if __name__ == '__main__':
    unittest.main()
